const index = $itemIndex;
const aiResp = $input.item.json;
const allCompanies = $node["Generate Suppliers"].json;
const company = Array.isArray(allCompanies) ? allCompanies[index] : allCompanies;

let ai = { ai_score: 7, recommended: 'YES', pros: 'Хороший рейтинг', risks: 'Проверьте документы' };

try {
  const parsed = JSON.parse(aiResp.choices[0].message.content);
  ai = { ai_score: parsed.ai_score || 7, recommended: parsed.recommended || 'YES', pros: parsed.pros || ai.pros, risks: parsed.risks || ai.risks };
} catch (e) {}

return {
  json: {
    company_name: company.company_name,
    rating: company.rating,
    moq: company.moq,
    price: company.price,
    location: company.location,
    contact_email: company.contact_email,
    company_url: company.company_url,
    category: company.category,
    chat_id: company.chat_id,
    user_id: company.user_id,
    user_name: company.user_name,
    ai_score: ai.ai_score,
    recommended: ai.recommended,
    pros: ai.pros,
    risks: ai.risks,
    timestamp: new Date().toISOString()
  }
};

const items = $input.all();
const chatId = items[0].json.chat_id;
const category = items[0].json.category;

let message = `📊 *${category}* (${items.length} компаний)\n\n`;

items.forEach((item, i) => {
  const d = item.json;
  const star = d.recommended === 'YES' ? '⭐️' : '📍';
  message += `${star} *${i+1}. ${d.company_name}*\n`;
  message += `🎯 AI: ${d.ai_score}/10 | 📊 ${d.rating}/5\n`;
  message += `📦 ${d.moq} | 💰 ${d.price}\n`;
  message += `📍 ${d.location}\n`;
  message += `📧 ${d.contact_email}\n`;
  message += `🌐 ${d.company_url}\n`;
  message += `✅ ${d.pros}\n`;
  message += `⚠️ ${d.risks}\n\n`;
});

message += `_Сохранено в Google Sheets_ 📝`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};
